"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["92871"],{88675(e){e.exports=JSON.parse('{"id":"V4-068","slug":"executive-compensation","term":"Executive Compensation","also_known_as":[],"difficulty":"Intermediate","definition":"Executive compensation is the total pay and benefits provided to a company\u2019s senior executives, typically including salary, annual bonuses, long-term incentives such as shares or options, pensions and other benefits.","explanation":["Executive pay packages usually have several parts. Base salary provides fixed pay. Annual bonuses reward short-term performance against targets. Long-term incentives, such as performance shares, restricted stock or stock options, aim to align executives\u2019 interests with shareholders\u2019 over several years. Pensions and benefits, such as health cover, make up the rest.","For example, a chief executive\u2019s package might consist of a salary of 1,000,000, a potential annual bonus of up to 150% of salary and long-term share awards worth up to three times salary if performance targets are met.","Because a large part of pay is often variable and linked to shares, actual pay can differ greatly from target pay, depending on performance and share prices.","Executive pay is set by the board\u2019s remuneration committee and disclosed in detail in the annual report. It is often controversial, with debates about its level compared with employees\u2019 pay, whether it rewards genuine performance or luck, and whether it encourages short-term thinking. Many countries require disclosure of the ratio between chief executive pay and typical employee pay."],"note":"","total":1725,"prev":{"slug":"exclusionary-screening","term":"Exclusionary Screening"},"next":{"slug":"exercise","term":"Exercise"}}')}}]);